using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using IdleIntelligence.Core;using IdleIntelligence.Runtime;using NUnit.Framework;using UnityEngine;using UnityEngine.UI;using UnityEngine.SceneManagement;using UnityEngine.TestTools;
namespace IdleIntelligence.PlayTests {
 public sealed class MetaVisualSectionTests {
  GameRuntime game;string directory;const string Output="/tmp/idle-meta-visual-review";
  [UnitySetUp]public IEnumerator Setup(){directory=Path.Combine(Path.GetTempPath(),"meta-visual-"+Guid.NewGuid());Directory.CreateDirectory(directory);Directory.CreateDirectory(Output);GameRuntime.SavePathOverride=Path.Combine(directory,"save.json");yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();game.Act(s=>NarrativeBridge.Action(s,"name","AURA"));for(int i=0;i<5;i++)game.Act(s=>NarrativeBridge.Action(s,"continue"));game.Act(s=>NarrativeBridge.Action(s,"skip-tutorial"));game.Act(s=>{var n=s.Copy();n.Legacy.prepared=true;n.Story.enabled=false;n.Story.open=null;n.Story.queue=Array.Empty<string>();n.Story.seen=NarrativeCatalog.Dialogues.Select(d=>d.Id).ToArray();n.Story.tutorial="skipped";return n;});}
  [UnityTearDown]public IEnumerator Cleanup(){if(game!=null)UnityEngine.Object.Destroy(game.gameObject);yield return null;GameRuntime.SavePathOverride=null;}
  [UnityTest]public IEnumerator AllMainSlotsHaveSameSizeAndNewItemsUseTheirOwnArt(){foreach(bool filled in new[]{false,true}){game.Act(s=>{var n=s.Copy();if(filled){n.Workshop.nodes=new[]{"H01","H02","H03","T01","T02","T03","F01","F02","F03","W01","W02","W03","S01","S02","S03","I01","I02","I03"};n.Workshop.permanentSlots=new[]{"processorAux","coreAux","researchAux"};n.Prestige.lab=true;n.Meta.resets=5;n.Meta.models[0]=3;n.Meta.models[1]=2;n.Meta.models[2]=1;n.Workshop.inventory=ItemBalance.Items.Skip(30).Select((d,i)=>new ItemInstance{id="meta-"+i,type=d.Id,level=12,rarity=i%6}).ToArray();}return n;});if(filled)foreach(var item in game.State.Workshop.inventory.ToArray())game.Act(s=>Workshop.Equip(s,item.id));foreach(string language in new[]{"de","en"}){game.Act(s=>SettingsRules.Change(s,"language",language));game.Show("items");yield return null;game.WorkshopView.ChangeMode("inventory");yield return null;var sockets=game.WorkshopView.Equipment.GetComponentsInChildren<ItemPortrait>().Where(p=>p.name.StartsWith("equipment-")).Take(6).ToArray();Assert.That(sockets.Length,Is.EqualTo(6));foreach(int width in new[]{320,390,430}){PortraitGameView.Set(width,width==320?694:width==390?846:932);yield return null;yield return null;Canvas.ForceUpdateCanvases();foreach(var socket in sockets){Assert.That(((RectTransform)socket.transform).rect.size,Is.EqualTo(new Vector2(88,88)),socket.name);Assert.That(socket.Art.raycastTarget,Is.False);}WorkshopTests.Capture(width,width==320?694:width==390?846:932,Output+"/loadout-"+(filled?"filled":"locked")+"-"+language+"-"+width+".png");}if(filled){Assert.That(game.WorkshopView.ItemSprites.Length,Is.EqualTo(36));foreach(var sprite in game.WorkshopView.ItemSprites.Skip(30))Assert.That(sprite.texture.name,Is.EqualTo("meta-items-v1"));game.WorkshopView.OpenItem("meta-5");yield return new WaitForSecondsRealtime(.55f);WorkshopTests.Capture(390,846,Output+"/item-detail-"+language+".png");game.WorkshopView.CloseDetail();}}}}
  [UnityTest]public IEnumerator BothNetworksUseDedicatedSymbolsAndKeepCostOnlyPurchases(){game.Act(s=>{var n=s.Copy();n.Prestige.Cycle=ScientificNumber.From(1e14);n.Prestige.Total=n.Prestige.Cycle;n.Prestige.Free=n.Prestige.Cycle;n.Prestige.Entitlement=n.Prestige.Cycle.Add(ScientificNumber.From(100));n.Meta.resets=1;n.Meta.available=ScientificNumber.From(1000000).ToData();n.Meta.total=n.Meta.available;return n;});game.Show("prestige");yield return null;var network=UnityEngine.Object.FindFirstObjectByType<PrestigeNetworkView>();foreach(string language in new[]{"de","en"})foreach(bool axiom in new[]{false,true}){game.Act(s=>SettingsRules.Change(s,"language",language));network.SetLayer(axiom);yield return null;var sprites=axiom?network.AxiomSprites:network.NodeSprites;Assert.That(sprites.Length,Is.EqualTo(axiom?24:60));foreach(var sprite in sprites)Assert.That(sprite.texture.name,Is.EqualTo("progression-symbols"));foreach(int width in new[]{320,390,430}){PortraitGameView.Set(width,width==320?694:width==390?846:932);yield return null;yield return null;Canvas.ForceUpdateCanvases();var tools=network.transform.Find("NetworkTools").GetComponentsInChildren<Button>();foreach(var control in tools){Assert.That(((RectTransform)control.transform).rect.width,Is.GreaterThanOrEqualTo(44),control.name);Assert.That(((RectTransform)control.transform).rect.width,Is.EqualTo(((RectTransform)tools[0].transform).rect.width).Within(1),"Image preferred widths cannot squeeze other tools");}WorkshopTests.Capture(width,width==320?694:width==390?846:932,Output+"/network-"+(axiom?"axiom":"int")+"-"+language+"-"+width+".png");}}Assert.That(PrestigeRules.Buy(game.State,"H10").Workshop.nodes,Does.Contain("H10"),"No predecessor gate");}
  [UnityTest]public IEnumerator MiraUsesActualExpressionsReducedMotionAndReloadWithoutRewards(){game.Show("story");yield return null;game.Act(s=>NarrativeBridge.Action(s,"reopen","prologue-welcome"));yield return null;yield return null;var portrait=UnityEngine.Object.FindFirstObjectByType<MiraMotion>();Assert.That(portrait,Is.Not.Null);var image=portrait.GetComponent<Image>();var times=new List<float>();string frames=Output+"/mira-motion";Directory.CreateDirectory(frames);game.Audio.Unlock();var listener=game.GetComponent<AudioListener>();if(listener!=null)listener.enabled=false;var probe=new GameObject("MetaReviewAudio",typeof(AudioListener),typeof(ReviewAudioCapture));probe.transform.SetParent(game.transform);var audio=probe.GetComponent<ReviewAudioCapture>();audio.Begin();double began=Time.realtimeSinceStartupAsDouble;int frame=0;while(Time.realtimeSinceStartupAsDouble-began<6){double age=Time.realtimeSinceStartupAsDouble-began;portrait.Cue=age<1.5?"explain":age<3?"warning":age<4.5?"success":"milestone";times.Add(Time.realtimeSinceStartup);WorkshopTests.Capture(390,846,frames+"/"+(frame++).ToString("D4")+".png");yield return null;}File.WriteAllLines(frames+"/times.txt",times.Select(t=>t.ToString("R",System.Globalization.CultureInfo.InvariantCulture)));audio.Save(frames);Assert.That(image.sprite.texture.name,Is.EqualTo("mira-expressions-v1"));var before=game.State.Workshop.inventory.Length;game.Act(s=>{var n=s.Copy();n.Workshop.reducedMotion=true;return n;});yield return new WaitForSecondsRealtime(.2f);var sprite=image.sprite;yield return new WaitForSecondsRealtime(.5f);Assert.That(image.sprite,Is.SameAs(sprite));Assert.That(game.State.Workshop.inventory.Length,Is.EqualTo(before));var loaded=new AtomicSaveStore(game.SavePath,new UnitySaveCodec()).Load(game.State.SavedAt);Assert.That(loaded.State.Workshop.reducedMotion,Is.True);WorkshopTests.Capture(390,846,Output+"/mira-reduced.png");}
  [UnityTest]public IEnumerator PrivacyAndDeletionRemainReachableWithoutPretendingAuthentication(){game.Show("company");yield return null;var api=UnityEngine.Object.FindFirstObjectByType<CompanyApiClient>();Assert.That(api==null||!api.HasSession,Is.True);foreach(string action in new[]{"CompanyVouchers","CompanyInvites","CompanyGoods"}){GameObject.Find(action).GetComponent<Button>().onClick.Invoke();yield return null;}GameObject.Find("CompanyPrivacy").GetComponent<Button>().onClick.Invoke();yield return null;Assert.That(GameObject.Find("MakeProfilePrivate"),Is.Not.Null);GameObject.Find("DeleteOnlineAccount").GetComponent<Button>().onClick.Invoke();yield return null;Assert.That(GameObject.Find("ConfirmAccountDeletion"),Is.Not.Null);Assert.That(GameObject.Find("CancelAccountDeletion"),Is.Not.Null);var before=game.State.Workshop.inventory.Length;GameObject.Find("ConfirmAccountDeletion").GetComponent<Button>().onClick.Invoke();yield return null;Assert.That(game.State.Workshop.inventory.Length,Is.EqualTo(before));Assert.That(api==null||!api.HasSession,Is.True);Assert.That(GameObject.Find("CompanyState").GetComponent<Text>().text,Does.Not.Contain("gelöscht"));WorkshopTests.Capture(390,846,Output+"/privacy-unavailable-provider.png");}

  [UnityTest]public IEnumerator RecordAllFourActualPaidChestTiersWithoutAnimationGrants(){game.Act(s=>{var n=s.Copy();n.Retention.gems=100000;return n;});game.Show("market");yield return null;PortraitGameView.Set(390,846);yield return null;game.Audio.Unlock();var listener=game.GetComponent<AudioListener>();if(listener!=null)listener.enabled=false;var probe=new GameObject("MetaChestAudio",typeof(AudioListener),typeof(ReviewAudioCapture));probe.transform.SetParent(game.transform);var audio=probe.GetComponent<ReviewAudioCapture>();audio.Begin();string folder=Output+"/chest-four-tiers";Directory.CreateDirectory(folder);var times=new List<string>();var receipts=new List<string>();float start=Time.realtimeSinceStartup;int frame=0;foreach(string tier in new[]{"common","rare","epic","legendary"}){float began=Time.realtimeSinceStartup;bool paid=false;long revision=game.State.Rewards.shopRevision;long gems=game.State.Retention.gems;while(Time.realtimeSinceStartup-began<3.5f){if(!paid&&Time.realtimeSinceStartup-began>.45f){paid=true;var button=GameObject.Find("MarketOffer-chest:"+tier).GetComponent<Button>();Assert.That(button.interactable,Is.True);button.onClick.Invoke();revision=game.State.Rewards.shopRevision;gems=game.State.Retention.gems;var load=new AtomicSaveStore(game.SavePath,new UnitySaveCodec()).Load(game.State.SavedAt);Assert.That(load.Writable,Is.True,load.Message);Assert.That(load.State.Rewards.shopRevision,Is.EqualTo(revision));var receipt=game.State.Rewards.receipt;receipts.Add(tier+" receipt="+revision+" item="+(receipt.hasItem?receipt.item.type+" rarity="+receipt.item.rarity:"none"));}times.Add((Time.realtimeSinceStartup-start).ToString("R",System.Globalization.CultureInfo.InvariantCulture));WorkshopTests.Capture(390,846,folder+"/"+(frame++).ToString("D4")+".png");yield return null;}Assert.That(game.State.Rewards.shopRevision,Is.EqualTo(revision));Assert.That(game.State.Retention.gems,Is.EqualTo(gems));Assert.That(game.GetComponent<RewardPresentation>().Current.IsAnimating,Is.False);}audio.Save(folder);File.WriteAllLines(folder+"/times.txt",times);File.WriteAllLines(folder+"/actual-receipts.txt",receipts);}

 }
}
